create or replace TABLE SZD_PRODUCTION.ETL.T_ETL_DIM_TICKET_CORE_REL_T_TICKET_A (
	AGREEMENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the agreement ticket. Key generation based on META table for party key space.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	AFFECTED_IT_RESOURCE_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the resource item as a affected IT ressource (CI). Key generation based on META table for party key space.',
	CAUSATIVE_IT_RESOURCE_RESOURCE_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the resource item as a causative IT ressource (CI). Key generation based on META table for party key space.',
	CALLER_BUSINESS_UNIT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the party as a business unit. It defines the business unit of the ticket caller.If the caller''s business unit is \empty\, the business unit is that from the ticket''s First Assignment Group. Key generation based on META table for party key space.',
	AFFECTED_COUNTRY_BUSINESS_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the location as business country.It corresponds either to the business country of the ticket caller (for Incident and Non Standard Request) or to the affected region(s) of a ticket Problem.If the caller''s region is \empty\,the region is that from the ticket''s First Assignment Group. Key generation based on META table for party key space. ',
	AFFECTED_DIVISION_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the party as a division. It corresponds either to the division of the ticket caller (for Incident and Non Standard Request) or to the affected divsion(s) of a ticket Problem. If the caller''s division is \empty\, the division is that from the ticket''s First Assignment Group. Key generation based on META table for party key space.',
	FIRST_ASSIGNMENT_USER_GROUP_PARTY_GROUP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the party group as first assignment user group. Key generation based on META table for party key space.',
	RESOLVING_USER_GROUP_PARTY_GROUP_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the party group as resolving group. Key generation based on META table for party key space.',
	TICKET_PRIORITY_ID NUMBER(38,0) NOT NULL COMMENT 'The code identifying the discriminators for tickets priority.',
	TICKET_CLOSING_REASON_ID NUMBER(38,0) NOT NULL COMMENT 'The code identifying the discriminators for ticket closing reasons',
	TICKET_CREATION_METHOD_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'The code identifying the discriminators for  ticket creation method type like Fullfiller or Enduserportal',
	PARENT_INCIDENT_AGREEMENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the agreement ticket of the master incident. Relation is only 1 Level',
	TICKET_CREATION_DT DATE NOT NULL COMMENT 'Ticket creation date - The day represented as a calendar date of the form YYYY-MM-DD. YYYY is the calendar year, MM (between 1 and 12) the calendar month and DD the day of the calendar month (between 1 and 31). ',
	TICKET_CREATION_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'Ticket creation timestamp - A point in time, identified by a date and a time component.',
	TICKET_RESOLVING_DT DATE COMMENT 'Due date of ticket accordingly to the business definition - The day represented as a calendar date of the form YYYY-MM-DD. YYYY is the calendar year, MM (between 1 and 12) the calendar month and DD the day of the calendar month (between 1 and 31). ',
	TICKET_RESOLVING_TMSP TIMESTAMP_TZ(9) COMMENT 'Ticket resolved timestamp (for Incident and Problem) /  Ticket completed timestamp (for NSR)  accordingly to the business definition - A point in time, identified by a date and a time component.',
	TICKET_CLOSING_DT DATE COMMENT 'Ticket closed date  - The day represented as a calendar date of the form YYYY-MM-DD. YYYY is the calendar year, MM (between 1 and 12) the calendar month and DD the day of the calendar month (between 1 and 31). ',
	TICKET_CLOSING_TMSP TIMESTAMP_TZ(9) COMMENT 'Ticket closed timestamp - A point in time, identified by a date and a time component.',
	TICKET_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'Natural Key/Business Key - The code identifying the discriminators for ticket types.',
	TICKET_NR VARCHAR(250) NOT NULL COMMENT 'Natural/Business Key -  Ticket Nummer (z.B. INC1234567) of a ticket created in e.g. IT4You.',
	TICKET_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description about the ticket.',
	TICKET_ACTIVE_FG BOOLEAN NOT NULL COMMENT 'Flag for ticket activity. TRUE - Ticket can be edited by the enduser. FALSE - Ticket cannot be edited by the enduser in IT4you.',
	MASTER_INCIDENT_FG BOOLEAN NOT NULL COMMENT 'Flag for indicating if the current incident is master incident',
	CALLER_BUSINESS_UNIT_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The textual name of a business unit.',
	AFFECTED_COUNTRY_BUSINESS_CD VARCHAR(3) NOT NULL COMMENT 'Denormalized Attribute - The code identifying the country according in the SCHWARZ group',
	AFFECTED_COUNTRY_BUSINESS_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The name by which the country is known,',
	AFFECTED_DIVISION_CD VARCHAR(50) NOT NULL COMMENT 'Denormalized Attribute - Natural/Business Key - The unique code for each division within the Schwarz Group, i.e.L-Lidl or K-Kaufland',
	AFFECTED_DIVISION_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The name for the division within the Schwarz Group, i.e.Lidl or Kaufland',
	FIRST_ASSIGNMENT_USER_GROUP_NR NUMBER(38,0) NOT NULL COMMENT 'Denormalized Attribute - Natural/Business Key - id of first assigned user group',
	FIRST_ASSIGNMENT_USER_GROUP_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - The group name by which the first assigned user group is identified on the system.',
	RESOLVING_USER_GROUP_NR NUMBER(38,0) COMMENT 'Denormalized Attribute - Natural/Business Key - id of resolving user group',
	RESOLVING_USER_GROUP_NAME VARCHAR(100) COMMENT 'Denormalized Attribute - The group name by which the resolving user group is identified on the system.',
	TICKET_PRIORITY_DESCR VARCHAR(250) NOT NULL COMMENT 'Denormalized Attribute - A textual description for the discriminators for priority',
	TICKET_CLOSING_REASON_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - A textual description for the discriminators for ticket closing reasons. Possible values: Article available in Servicecatalog, Duplicate Ticket, Knowledge trasfer to user, Non-IT Reason, Request cancelled by user, Request completed successully, Declined',
	TICKET_CREATION_METHOD_TYPE_NAME VARCHAR(100) NOT NULL COMMENT 'Denormalized Attribute - A textual description for the discriminators for ticket creation method type',
	SOURCE_SYS_NR VARCHAR(100) NOT NULL COMMENT 'Source system payload attribute - Technical Surrogate Key (surves as Natural Key) - additional technical system id for identification of tickets.',
	SOURCE_UPDATED_ON_TMSP TIMESTAMP_TZ(9) COMMENT 'Source system payload attribute - The point in time when this record was last modified in the source system. (In case the record has not been modified since its creation, source_updated_on is identical to creation timestamp)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_DIM_TICKET primary key (AGREEMENT_SID, DWH_VALID_FROM_TMSP)
);